// Obtener el mensaje principal
const message = items[0].json.body;

// Texto del mensaje
const content = message.content || "";

// Adjuntos
const attachments = message.attachments || [];

// Regex → generar URL interna
function makeInternal(url) {
  if (!url) return url;

  return url.replace(
    /^https:\/\/([a-zA-Z0-9\-]+)\.ocm\.aigentss\.cloud/,
    'http://$1.ocm.aigentss.cloud:3000'
  );
}

// ------------------------------------
// Procesar TODOS los attachments
// ------------------------------------
const processedAttachments = attachments.map(att => ({
  ...att,
  data_url_external: att.data_url || null,
  data_url_internal: makeInternal(att.data_url),
  thumb_url_external: att.thumb_url || null,
  thumb_url_internal: makeInternal(att.thumb_url)
}));

// ------------------------------------
// Detectar tipos presentes en el mensaje
// ------------------------------------
let type = "unknown";

// Caso: solo texto
if (attachments.length === 0 && content.trim() !== "") {
  type = "text";

// Caso: hay adjuntos
} else if (attachments.length > 0) {

  // Si TODOS son imágenes
  if (attachments.every(a => a.file_type === "image")) {
    type = content.trim() !== "" ? "image_with_text" : "image";
  }

  // Si TODOS son audios
  else if (attachments.every(a => a.file_type === "audio")) {
    type = "audio";

  // Si TODOS son location
  } else if (attachments.every(a => a.file_type === "location")) {
    type = "location";

  // Mezcla de adjuntos → híbrido
  } else {
    type = "mixed";
  }
}

return [
  {
    json: {
      type,
      content_text: content,
      attachments: processedAttachments,
      raw: items[0].json
    }
  }
];

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

// Extraer coordenadas del attachment
const attachment = node.attachments?.[0] || {};
const lat = attachment.coordinates_lat || null;
const lon = attachment.coordinates_long || null;

// Construir el content_text para el siguiente nodo
//const content = {
//  lat,
//  lon
//};
const content = `${lat}, ${lon}`;

let result = {
  type: node.type,
  content: content,   // aquí va listo para el agente
  raw: editFields
};

return [{ json: result }];

const out = [];

for (const item of $input.all()) {
  const type = item.json.type;

  if (type === "text" || type === "image_with_text") {
    out.push({
      json: {
        content: item.json.content_text,
        type: "text"
      }
    });
  } else {
    out.push(item);
  }
}

return out;

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

let result = {
  type: node.type,
  content_text: node.content,
  raw: editFields

};

return [{ json: result }];

const msgs = $json.output.messages || [];
return msgs.map((m, i) => ({
  message: m,
  indx: i
}));

const input = items[0].json;

const message =
  input.message ||
  input.content ||
  input.caption ||
  'Mensaje enviado desde backend';

// busca base64 en varios campos
let b64 = input.image_base64 || input.base64 || input.file_base64 || null;

// si NO hay adjunto, devolver solo texto (sin binary)
if (!b64) {
  return [{
    json: {
      message,
      hasAttachment: false
    }
  }];
}

// si hay base64, preparar binario
let mimeType = input.mimeType || input.mime_type || 'image/png';
let fileName = input.fileName || input.filename || 'archivo';

// si viene como dataURL: data:image/png;base64,xxxx
if (typeof b64 === 'string' && b64.startsWith('data:')) {
  const [meta, data] = b64.split(',');
  b64 = data;
  const m = meta.match(/^data:(.*?);base64$/);
  if (m && m[1]) mimeType = m[1];
}

// nombre por defecto según mime
if (fileName === 'archivo') {
  if (mimeType.includes('png')) fileName = 'imagen.png';
  else if (mimeType.includes('jpeg') || mimeType.includes('jpg')) fileName = 'imagen.jpg';
  else if (mimeType.includes('pdf')) fileName = 'archivo.pdf';
  else if (mimeType.includes('ogg')) fileName = 'audio.ogg';
  else if (mimeType.includes('mpeg') || mimeType.includes('mp3')) fileName = 'audio.mp3';
}

const buffer = Buffer.from(b64, 'base64');

return [{
  json: {
    message,
    hasAttachment: true
  },
  binary: {
    data: {
      data: buffer,
      mimeType,
      fileName
    }
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "reply": {
      "type": "object",
      "properties": {
        "text": { "type": "string" },
        "channel_hints": {
          "type": "object",
          "properties": {
            "send_typing": { "type": "boolean" },
            "attachments": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "type": { "type": "string" },
                  "url": { "type": "string" }
                },
                "required": ["type", "url"],
                "additionalProperties": false
              }
            }
          },
          "required": ["send_typing", "attachments"],
          "additionalProperties": false
        }
      },
      "required": ["text"],
      "additionalProperties": false
    },
    "intents": {
      "type": "object",
      "properties": {
        "primary": { "type": "string" },
        "confidence": { "type": "number" },
        "pending_intent": { "type": ["string", "null"] },
        "pending_intent_resolved": { "type": "boolean" }
      },
      "required": ["primary", "pending_intent", "pending_intent_resolved"],
      "additionalProperties": false
    },
    "profile": {
      "type": "object",
      "properties": {
        "missing_fields": { "type": "array", "items": { "type": "string" } },
        "captured": {
          "type": "object",
          "properties": {
            "name": { "type": "string" },
            "identifier": { "type": "string" },
            "email": { "type": "string" },
            "service": { "type": "string" }
          },
          "additionalProperties": false
        },
        "tac": {
          "type": "object",
          "properties": {
            "needs_acceptance": { "type": "boolean" },
            "accepted_now": { "type": "boolean" }
          },
          "required": ["needs_acceptance", "accepted_now"],
          "additionalProperties": false
        }
      },
      "required": ["missing_fields", "captured", "tac"],
      "additionalProperties": false
    },
    "actions": {
      "type": "object",
      "properties": {
        "update_contact": {
          "type": "object",
          "properties": {
            "should_update": { "type": "boolean" },
            "patch": {
              "type": "object",
              "properties": {
                "name": { "type": "string" },
                "identifier": { "type": "string" },
                "email": { "type": "string" },
                "tac": { "type": "boolean" }
              },
              "additionalProperties": false
            }
          },
          "required": ["should_update", "patch"],
          "additionalProperties": false,
          "allOf": [
            {
              "if": {
                "properties": { "should_update": { "const": false } },
                "required": ["should_update"]
              },
              "then": {
                "properties": { "patch": { "maxProperties": 0 } }
              }
            }
          ]
        },
        "update_conversation": {
          "type": "object",
          "properties": {
            "should_update": { "type": "boolean" },
            "custom_attributes_patch": {
              "type": "object",
              "properties": {
                "pending_intent": { "type": ["string", "null"] },
                "pending_intent_resolved": { "type": ["boolean", "null"] }
              },
              "additionalProperties": false
            }
          },
          "required": ["should_update", "custom_attributes_patch"],
          "additionalProperties": false,
          "allOf": [
            {
              "if": {
                "properties": { "should_update": { "const": false } },
                "required": ["should_update"]
              },
              "then": {
                "properties": { "custom_attributes_patch": { "maxProperties": 0 } }
              }
            }
          ]
        },
        "handover_to_human": {
          "type": "object",
          "properties": {
            "should_handover": { "type": "boolean" },
            "reason": { "type": ["string", "null"] },
            "priority": { "type": "string" }
          },
          "required": ["should_handover", "reason", "priority"],
          "additionalProperties": false
        },
        "schedule": {
          "type": "object",
          "properties": {
            "command": { "type": "string", "enum": ["none", "availability", "book", "cancel"] },

            "establishment_query": { "type": ["string", "null"] },
            "establishment_id": { "type": ["integer", "null"] },

            "service": { "type": ["string", "null"] },
            "service_id": { "type": ["integer", "null"] },

            "date": { "type": ["string", "null"], "description": "YYYY-MM-DD" },
            "time": { "type": ["string", "null"], "description": "HH:mm 24h" },

            "timezone": { "type": "string" },

            "start_at": { "type": ["string", "null"], "description": "ISO8601 (timestamptz)" },

            "appointment_id": { "type": ["integer", "null"] },

            "customer_name": { "type": ["string", "null"] },
            "customer_phone": { "type": ["string", "null"] },
            "customer_email": { "type": ["string", "null"] },

            "notes": { "type": ["string", "null"] }
          },
          "required": ["command", "timezone"],
          "additionalProperties": false,
          "allOf": [
            {
              "if": { "properties": { "command": { "const": "availability" } } },
              "then": {
                "required": ["date"],
                "anyOf": [
                  { "required": ["establishment_id"] },
                  { "required": ["establishment_query"] }
                ],
                "anyOf": [
                  { "required": ["service_id"] },
                  { "required": ["service"] }
                ]
              }
            },
            {
              "if": { "properties": { "command": { "const": "book" } } },
              "then": {
                "required": ["establishment_id", "service_id", "start_at", "customer_name"]
              }
            },
            {
              "if": { "properties": { "command": { "const": "cancel" } } },
              "then": {
                "required": ["appointment_id"]
              }
            }
          ]
        }
      },
      "required": ["update_contact", "update_conversation", "handover_to_human", "schedule"],
      "additionalProperties": false
    }
  },
  "required": ["reply", "intents", "profile", "actions"],
  "additionalProperties": false
}
